"""Correct the can's material planes; keep source geometry and tier scales fixed."""
from pathlib import Path
import json
HERE=Path(__file__).resolve().parent;jobs=[]
for tier,details in [('basic','The entire metal pail body, arched metal handle and spout are dull dark worn metal: ink_soft, stone_dark and stone planes, with a few muted brown rust patches. No large ivory or bright silver planes. A tiny pale glint is allowed, but less than five percent of the pail.'),('gold','The entire metal pail body, arched metal handle, spout and rose are muted GOLD metal: gold_dark RGB168,116,44; gold RGB196,150,70; gold_light RGB214,186,96. No large silver, grey or ivory surfaces remain. A tiny pale glint is allowed, but less than five percent of the pail. No orange fire, coins or glow.')]:
    prompt='Use case: precise-object-edit. Image1 is the exact '+tier+' watering-can edit target. Change ONLY its metal MATERIAL COLOURS. '+details+' Preserve every silhouette pixel cluster, canvas, margin, part shape, handle arch, spout, rose, size, position and lighting direction. Do not crop, recenter, add parts or redraw geometry. The source is a complete1254x1254 square, reduced to16x16 and10x10, so material planes must be broad and readable. No labels, panel, scene, water, ground or shadow. Real transparent alpha outside the one can.\n'
    args={'prompt':prompt,'referenced_image_paths':[str(HERE/f'raw/can_{tier}-r1.png')],'transparent_background':True};stem='can_'+tier+'-r2';jobs.append({'folder':HERE.name,'stem':stem,'revision':2,'args':args});(HERE/f'raw/{stem}.request.json').write_text(json.dumps(args,indent=2)+'\n',encoding='utf-8');(HERE/f'raw/{stem}.prompt.txt').write_text(prompt,encoding='utf-8')
(HERE/'can-material-fix-jobs.json').write_text(json.dumps(jobs,indent=2)+'\n',encoding='utf-8')
